47: export function heuristicCritique(
48:   doc: UiDocument,
49:   viewport: ViewportMode = "desktop",
50: ): DesignCritiqueResult {
51:   const findings: CritiqueFinding[] = [];
52:   const resolvedRoot = resolveDocument(doc, viewport);
53:   const resolvedById = new Map<string, ResolvedElement>();
54:   const index = (element: ResolvedElement) => {
55:     resolvedById.set(element.id, element);
56:     element.children?.forEach(index);
57:   };
58:   index(resolvedRoot);
59: 
60:   const spacingScale = new Set(Object.values(defaultTokens.spacing));
61:   const fontScale = new Set([
62:     defaultTokens.typography.fontSizeXs,
63:     defaultTokens.typography.fontSizeSm,
64:     defaultTokens.typography.fontSizeBase,
65:     defaultTokens.typography.fontSizeLg,
66:     defaultTokens.typography.fontSizeXl,
67:     defaultTokens.typography.fontSize2xl,
68:     defaultTokens.typography.fontSize3xl,
69:     36,
70:     48,
71:   ]);
72:   const palette = themePalette(doc);
73:   const explicitFontSizes = new Set<number>();
74:   const offPaletteColors = new Set<string>();
75:   let maxDepth = 0;
76:   let prominentHeading = false;
77: 
78:   const walk = (
79:     node: UiNode,
80:     depth: number,
81:     inheritedBackground: string,
82:     inheritedColor: string,
83:   ) => {
84:     if (node.hidden) return;
85:     const element = resolvedById.get(node.id);
86:     if (!element) return;
87: 
88:     maxDepth = Math.max(maxDepth, depth);
89:     const override = viewport === "desktop" ? undefined : node.responsive?.[viewport];
90:     const explicit: Record<string, unknown> = { ...(node.styles ?? {}), ...(override ?? {}) };
91: 
92:     const background =
93:       typeof element.styles.backgroundColor === "string"
94:         ? element.styles.backgroundColor
95:         : inheritedBackground;
96:     const color =
97:       typeof element.styles.color === "string" ? element.styles.color : inheritedColor;
98: 
99:     // --- Contrast ----------------------------------------------------------
100:     const fontSize =
101:       numericStyle(explicit.fontSize) ?? numericStyle(element.styles.fontSize) ?? 16;
102:     const fontWeight = numericStyle(element.styles.fontWeight) ?? 400;
103:     if (hasText(element) && fontSize >= 20 && fontWeight >= 600) {
104:       prominentHeading = true;
105:     }
106:     if (hasText(element)) {
107:       const fg = parseHexColor(color);
108:       const bg = parseHexColor(background);
109:       if (fg && bg) {
110:         const ratio = contrastRatio(fg, bg);
111:         const large = fontSize >= 24 || (fontSize >= 18.66 && fontWeight >= 700);
112:         const required = large ? MIN_LARGE_CONTRAST : MIN_CONTRAST;
113:         if (ratio < required) {
114:           findings.push({
115:             id: `contrast:${node.id}`,
116:             category: "contrast",
117:             severity: "high",
118:             title: "Độ tương phản chưa đạt WCAG AA",
119:             detail: `${element.label} (${node.id}) có tỉ lệ ${ratio.toFixed(2)}:1, cần tối thiểu ${required}:1.`,
120:             suggestion: `Đổi màu chữ sang ${bestTextColor(background, doc)} hoặc làm nền sáng/tối hơn.`,
121:             nodeId: node.id,
122:             fixStyles: { color: bestTextColor(background, doc) },
123:           });
124:         }
125:       }
126:     }
127: 
128:     // --- Spacing -----------------------------------------------------------
129:     for (const key of ["padding", "margin", "gap"]) {
