104:   switch (node.type) {
105:     case "dashboard.stats":
106:       // Data components are always refreshed.
107:       return true;
108:     case "dashboard.table":
109:       if (key === "headers") return isGenericHeaders(value);
110:       return true;
111:     case "dashboard.chart":
112:       if (key === "kind") return typeof value !== "string" || value.trim() === "";
113:       return isGenericText(value, locale, "title");
