183:   const hint = [context, doc.name, headingHint(doc)].filter(Boolean).join(" ");
184:   const topic = detectTopic(hint);
185:   const changes = targets.map((target) => buildChange(target, topic, locale));
186: 
187:   return {
188:     changes,
189:     summary:
190:       locale === "vi"
191:         ? `Đã tạo dữ liệu mẫu cho ${changes.length} thành phần (${topicLabel(topic, locale)}).`
192:         : `Generated sample data for ${changes.length} components (${topicLabel(topic, locale)}).`,
193:     source: "heuristic",
194:   };
195: }
196: 
197: function buildChange(
198:   target: DummyTarget,
199:   topic: DummyDataTopic,
200:   locale: DummyDataLocale,
201: ): DummyDataChange {
202:   const { node, props } = target;
203:   const generated = generateProps(node, topic, locale);
204:   const selected: Record<string, unknown> = {};
205:   for (const key of props) {
206:     if (generated[key] !== undefined) selected[key] = generated[key];
207:   }
208:   return {
209:     nodeId: node.id,
210:     nodeType: node.type,
211:     nodeLabel: target.label,
212:     props: selected,
213:   };
214: }
215: 
216: function generateProps(
217:   node: UiNode,
218:   topic: DummyDataTopic,
219:   locale: DummyDataLocale,
220: ): Record<string, unknown> {
221:   switch (node.type) {
222:     case "dashboard.stats": {
223:       const items = statLabels(topic, locale);
224:       return { items, values: items.map((item) => statValue(item, locale)) };
225:     }
226:     case "dashboard.table": {
227:       const existing = Array.isArray(node.props?.headers)
228:         ? (node.props.headers as unknown[]).map(String)
229:         : [];
230:       const headers = isGenericHeaders(existing)
231:         ? tableHeaders(topic, locale)
232:         : existing.slice(0, MAX_ARRAY_ITEMS);
233:       return { headers, rows: tableRows(headers, locale) };
234:     }
235:     case "dashboard.chart":
236:       return { title: chartTitle(topic, locale), kind: "bar" };
237:     case "dashboard.header":
238:       return headerCopy(topic, locale);
239:     case "basic.text":
240:       return { text: bodyCopy(topic, locale) };
241:     case "basic.button":
242:       return { label: buttonCopy(topic, locale) };
243:     case "basic.input":
244:       return inputCopy(topic, locale);
245:     case "basic.image":
246:       return { alt: locale === "vi" ? "Ảnh minh họa sản phẩm" : "Product illustration" };
247:     case "formal.card":
248:       return { title: cardTitle(topic, locale) };
249:     case "formal.form":
250:       return { title: locale === "vi" ? "Thông tin khách hàng" : "Customer information" };
251:     case "layout.section":
252:       return { title: sectionTitle(topic, locale) };
253:     default:
254:       return {};
255:   }
256: }
