260: /**
261:  * Validate and normalize model-proposed props. Returns null when nothing
262:  * usable remains. Unknown keys and malformed values are dropped.
263:  */
264: export function sanitizeDummyProps(
265:   nodeType: string,
266:   props: Record<string, unknown>,
267: ): Record<string, unknown> | null {
268:   const allowed = DUMMY_DATA_PROPS[nodeType];
269:   if (!allowed) return null;
270: 
271:   const clean: Record<string, unknown> = {};
272:   for (const key of allowed) {
273:     if (!(key in props)) continue;
274:     const value = sanitizeValue(key, props[key]);
275:     if (value !== undefined) clean[key] = value;
276:   }
277: 
278:   // Keep parallel arrays consistent.
279:   if (Array.isArray(clean.items) && Array.isArray(clean.values)) {
280:     const length = Math.min(clean.items.length, clean.values.length);
281:     clean.items = clean.items.slice(0, length);
282:     clean.values = clean.values.slice(0, length);
283:   }
284: 
285:   // Every table row must match the header count.
286:   if (Array.isArray(clean.headers) && Array.isArray(clean.rows)) {
287:     const columns = clean.headers.length;
288:     const rows = (clean.rows as unknown[][]).filter(
289:       (row) => Array.isArray(row) && row.length === columns,
290:     );
291:     if (rows.length === 0) delete clean.rows;
292:     else clean.rows = rows;
293:   }
294: 
295:   return Object.keys(clean).length > 0 ? clean : null;
296: }
297: 
298: function sanitizeValue(key: string, value: unknown): unknown {
299:   if (key === "kind") {
300:     return typeof value === "string" &&
301:       ["bar", "line", "area", "pie"].includes(value.trim())
302:       ? value.trim()
303:       : undefined;
304:   }
305: 
306:   if (key === "items" || key === "values" || key === "headers") {
307:     if (!Array.isArray(value)) return undefined;
308:     const items = value
309:       .map((item) => (typeof item === "string" ? item.trim() : String(item ?? "").trim()))
310:       .filter((item) => item.length > 0)
311:       .slice(0, MAX_ARRAY_ITEMS)
312:       .map((item) => item.slice(0, MAX_STRING_LENGTH));
313:     return items.length > 0 ? items : undefined;
314:   }
315: 
316:   if (key === "rows") {
317:     if (!Array.isArray(value)) return undefined;
318:     const rows = value
319:       .slice(0, MAX_TABLE_ROWS)
320:       .map((row) =>
321:         Array.isArray(row)
322:           ? row
323:               .slice(0, MAX_ARRAY_ITEMS)
324:               .map((cell) => String(cell ?? "").trim().slice(0, MAX_STRING_LENGTH))
325:           : [],
326:       )
327:       .filter((row) => row.length > 0);
328:     return rows.length > 0 ? rows : undefined;
329:   }
330: 
331:   if (typeof value !== "string") return undefined;
332:   const text = value.trim();
333:   if (text.length === 0) return undefined;
334:   return text.slice(0, MAX_STRING_LENGTH);
335: }
