339: export function detectTopic(hint: string): DummyDataTopic {
340:   const text = hint.toLowerCase();
341:   if (/đơn hàng|order|giao hàng|shipping|vận chuyển/.test(text)) return "orders";
342:   if (/khách hàng|customer|user|người dùng|account|tài khoản/.test(text)) {
343:     return "customers";
344:   }
345:   if (/sản phẩm|product|kho|inventory|hàng hóa|catalog/.test(text)) return "products";
346:   if (/chiến dịch|campaign|marketing|quảng cáo|email/.test(text)) return "marketing";
347:   if (/doanh thu|revenue|tài chính|finance|bán hàng|sales|báo cáo|report|dashboard/.test(text)) {
348:     return "sales";
349:   }
350:   return "generic";
351: }
