1: // ---------------------------------------------------------------------------
2: // Accessibility analysis (plan/07 3.6) — deterministic, rule-based checks over
3: // the resolved document. Runs locally (no AI key required) and produces safe
4: // style fixes that are applied through the normal command manager.
5: //
6: // Rules covered:
7: //  - contrast: WCAG 2.1 AA text/background ratio (4.5:1, 3:1 for large text)
8: //  - missing-alt: images without an alt description
9: //  - missing-label: buttons/inputs without any label or placeholder
10: //  - small-text: explicit font sizes below 12px
11: //  - small-target: buttons/inputs smaller than 32px on either axis
12: // ---------------------------------------------------------------------------
13: 
14: import type { Theme, UiDocument, ViewportMode } from "@ai-mockup-studio/ui-schema";
15: import {
16:   applyPatchBatch,
17:   resolveDocument,
18:   type ResolvedElement,
19: } from "@ai-mockup-studio/ui-renderer";
20: 
21: export type AccessibilityRule =
22:   | "contrast"
23:   | "missing-alt"
24:   | "missing-label"
25:   | "small-text"
26:   | "small-target";
27: 
28: export interface AccessibilityIssue {
29:   /** Stable id (`rule:nodeId`) for list keys and targeted fixes. */
30:   id: string;
31:   rule: AccessibilityRule;
32:   severity: "error" | "warning";
33:   nodeId: string;
34:   nodeType: string;
35:   nodeLabel: string;
36:   message: string;
37:   suggestion: string;
38:   /** Safe style patch that resolves the issue (contrast/text/target). */
39:   fixStyles?: Record<string, unknown>;
40: }
41: 
42: const MIN_CONTRAST = 4.5;
43: const MIN_LARGE_CONTRAST = 3;
44: const MIN_FONT_SIZE = 12;
45: const FIX_FONT_SIZE = 14;
46: const MIN_TARGET = 32;
47: const FIX_TARGET = 32;
48: 
49: /** Component types that render user-visible text, and which props hold it. */
50: const TEXT_PROPS: Record<string, string[]> = {
51:   "basic.text": ["text"],
52:   "basic.button": ["label"],
53:   "basic.input": ["label", "placeholder"],
54:   "dashboard.header": ["title", "subtitle"],
55:   "dashboard.chart": ["title"],
56:   "dashboard.table": ["headers"],
57:   "dashboard.stats": ["items"],
58:   "formal.card": ["title"],
59:   "formal.form": ["title"],
60: };
61: 
62: export function analyzeAccessibility(
63:   doc: UiDocument,
64:   viewport: ViewportMode = "desktop",
65: ): AccessibilityIssue[] {
66:   const resolved = resolveDocument(doc, viewport);
67:   const issues: AccessibilityIssue[] = [];
68: 
69:   const visit = (
70:     el: ResolvedElement,
71:     inheritedBackground: string,
72:     inheritedColor: string,
73:   ) => {
74:     if (el.hidden) return;
75: 
76:     const styles = el.styles;
77:     const background =
78:       typeof styles.backgroundColor === "string"
79:         ? styles.backgroundColor
80:         : inheritedBackground;
81:     const color =
82:       typeof styles.color === "string" ? styles.color : inheritedColor;
83: 
84:     checkContrast(el, color, background, doc.theme, issues);
85:     checkMissingAlt(el, issues);
86:     checkMissingLabel(el, issues);
87:     checkSmallText(el, issues);
88:     checkSmallTarget(el, issues);
89: 
90:     for (const child of el.children ?? []) {
91:       visit(child, background, color);
92:     }
93:   };
94: 
95:   visit(resolved, doc.theme.background, doc.theme.foreground);
96:   return issues;
97: }
98: 
99: /**
100:  * Build the next immutable document with all safe fixes applied. Returns null
101:  * when there is nothing to fix (only manual issues such as missing alt text).
102:  */
103: export function applyAccessibilityFixes(
104:   doc: UiDocument,
105:   issues: AccessibilityIssue[],
106:   viewport: ViewportMode = "desktop",
107: ): UiDocument | null {
108:   const byNode = new Map<string, Record<string, unknown>>();
109:   for (const issue of issues) {
110:     if (!issue.fixStyles) continue;
111:     byNode.set(issue.nodeId, {
112:       ...(byNode.get(issue.nodeId) ?? {}),
113:       ...issue.fixStyles,
114:     });
115:   }
116:   if (byNode.size === 0) return null;
117:   return applyPatchBatch(
118:     doc,
119:     [...byNode].map(([targetId, styles]) => {
120:       // Fixes for a tablet/mobile audit become breakpoint overrides so the
121:       // desktop layout is not silently changed.
122:       if (viewport === "desktop") {
123:         return { op: "style" as const, targetId, styles };
124:       }
125:       return {
126:         op: "update" as const,
127:         targetId,
128:         changes: Object.fromEntries(
129:           Object.entries(styles).map(([key, value]) => [
130:             `responsive.${viewport}.${key}`,
131:             value,
132:           ]),
133:         ),
134:       };
135:     }),
136:   );
137: }
138: 
139: // --- Rules -----------------------------------------------------------------
140: 
141: function checkContrast(
142:   el: ResolvedElement,
143:   color: string,
144:   background: string,
145:   theme: Theme,
146:   issues: AccessibilityIssue[],
147: ) {
148:   if (!hasText(el)) return;
149:   const fg = parseHexColor(color);
150:   const bg = parseHexColor(background);
151:   if (!fg || !bg) return;
152: 
153:   const ratio = contrastRatio(fg, bg);
154:   const fontSize = numericStyle(el.styles.fontSize) ?? 16;
155:   const bold =
156:     numericStyle(el.styles.fontWeight) !== undefined
157:       ? Number(el.styles.fontWeight) >= 700
158:       : false;
159:   const large = fontSize >= 24 || (fontSize >= 18.66 && bold);
160:   const required = large ? MIN_LARGE_CONTRAST : MIN_CONTRAST;
161:   if (ratio >= required) return;
162: 
163:   const fixed = bestTextColor(background, theme);
164:   issues.push({
165:     id: `contrast:${el.id}`,
166:     rule: "contrast",
167:     severity: "error",
168:     nodeId: el.id,
169:     nodeType: el.type,
170:     nodeLabel: el.label,
171:     message: `Độ tương phản ${ratio.toFixed(2)}:1 (cần ≥ ${required}:1)`,
172:     suggestion: `Đổi màu chữ sang ${fixed} để đạt ngưỡng WCAG AA.`,
173:     fixStyles: { color: fixed },
174:   });
175: }
176: 
177: function checkMissingAlt(el: ResolvedElement, issues: AccessibilityIssue[]) {
178:   if (el.type !== "basic.image") return;
179:   const alt = el.props.alt;
180:   if (typeof alt === "string" && alt.trim().length > 0) return;
181:   issues.push({
182:     id: `missing-alt:${el.id}`,
183:     rule: "missing-alt",
184:     severity: "warning",
185:     nodeId: el.id,
186:     nodeType: el.type,
187:     nodeLabel: el.label,
188:     message: "Ảnh thiếu mô tả alt",
189:     suggestion: "Mô tả nội dung ảnh hoặc đặt alt rỗng nếu ảnh chỉ trang trí.",
190:   });
191: }
192: 
193: function checkMissingLabel(el: ResolvedElement, issues: AccessibilityIssue[]) {
194:   if (el.type !== "basic.button" && el.type !== "basic.input") return;
195:   const candidates = ["label", "placeholder", "ariaLabel", "aria-label"];
196:   const labelled = candidates.some((key) => {
197:     const value = el.props[key];
198:     return typeof value === "string" && value.trim().length > 0;
199:   });
200:   if (labelled) return;
201:   issues.push({
202:     id: `missing-label:${el.id}`,
203:     rule: "missing-label",
204:     severity: "warning",
205:     nodeId: el.id,
206:     nodeType: el.type,
207:     nodeLabel: el.label,
208:     message:
209:       el.type === "basic.button" ? "Nút thiếu nhãn" : "Trường nhập thiếu nhãn",
210:     suggestion:
211:       el.type === "basic.button"
212:         ? "Thêm prop label mô tả hành động của nút."
213:         : "Thêm label hoặc placeholder để người dùng biết cần nhập gì.",
214:   });
215: }
216: 
217: function checkSmallText(el: ResolvedElement, issues: AccessibilityIssue[]) {
218:   if (!hasText(el)) return;
219:   const fontSize = numericStyle(el.styles.fontSize);
220:   if (fontSize === undefined || fontSize >= MIN_FONT_SIZE) return;
221:   issues.push({
222:     id: `small-text:${el.id}`,
223:     rule: "small-text",
224:     severity: "warning",
225:     nodeId: el.id,
226:     nodeType: el.type,
227:     nodeLabel: el.label,
228:     message: `Cỡ chữ ${fontSize}px nhỏ hơn ${MIN_FONT_SIZE}px`,
229:     suggestion: `Tăng cỡ chữ lên ${FIX_FONT_SIZE}px để dễ đọc.`,
230:     fixStyles: { fontSize: FIX_FONT_SIZE },
231:   });
232: }
233: 
234: function checkSmallTarget(el: ResolvedElement, issues: AccessibilityIssue[]) {
235:   if (el.type !== "basic.button" && el.type !== "basic.input") return;
236:   const width = numericStyle(el.styles.width);
237:   const height = numericStyle(el.styles.height);
238:   const tooSmall =
239:     (width !== undefined && width < MIN_TARGET) ||
240:     (height !== undefined && height < MIN_TARGET);
241:   if (!tooSmall) return;
242: 
243:   const fixStyles: Record<string, unknown> = {};
244:   if (width !== undefined && width < MIN_TARGET) fixStyles.width = FIX_TARGET;
245:   if (height !== undefined && height < MIN_TARGET) fixStyles.height = FIX_TARGET;
246: 
247:   const size = [width, height]
248:     .map((value) => (value === undefined ? "auto" : `${value}px`))
249:     .join(" × ");
250:   issues.push({
251:     id: `small-target:${el.id}`,
252:     rule: "small-target",
253:     severity: "warning",
254:     nodeId: el.id,
255:     nodeType: el.type,
256:     nodeLabel: el.label,
257:     message: `Vùng bấm ${size} nhỏ hơn ${MIN_TARGET}px`,
258:     suggestion: `Tăng kích thước lên tối thiểu ${FIX_TARGET}px.`,
259:     fixStyles,
260:   });
261: }
262: 
263: // --- Helpers ---------------------------------------------------------------
264: 
265: function hasText(el: ResolvedElement): boolean {
266:   const keys = TEXT_PROPS[el.type];
267:   if (!keys) return false;
268:   return keys.some((key) => {
269:     const value = el.props[key];
270:     if (typeof value === "string") return value.trim().length > 0;
271:     if (Array.isArray(value)) {
272:       return value.some((item) => String(item ?? "").trim().length > 0);
273:     }
274:     return false;
275:   });
276: }
277: 
278: /** Read a numeric style value (number or "Npx"). */
279: function numericStyle(value: unknown): number | undefined {
280:   if (typeof value === "number" && Number.isFinite(value)) return value;
281:   if (typeof value === "string") {
282:     const match = /^(-?\d+(?:\.\d+)?)px$/.exec(value.trim());
283:     if (match) return Number(match[1]);
284:   }
285:   return undefined;
286: }
287: 
288: interface Rgb {
289:   r: number;
290:   g: number;
291:   b: number;
292: }
293: 
294: function parseHexColor(value: string): Rgb | null {
295:   const hex = value.trim();
296:   const short = /^#([0-9a-f]{3})$/i.exec(hex);
297:   if (short) {
298:     return {
299:       r: parseInt(short[1][0] + short[1][0], 16),
300:       g: parseInt(short[1][1] + short[1][1], 16),
301:       b: parseInt(short[1][2] + short[1][2], 16),
302:     };
303:   }
304:   const long = /^#([0-9a-f]{6})$/i.exec(hex);
305:   if (!long) return null;
306:   return {
307:     r: parseInt(long[1].slice(0, 2), 16),
308:     g: parseInt(long[1].slice(2, 4), 16),
309:     b: parseInt(long[1].slice(4, 6), 16),
310:   };
311: }
312: 
313: function relativeLuminance({ r, g, b }: Rgb): number {
314:   const channel = (value: number) => {
315:     const v = value / 255;
316:     return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4;
317:   };
318:   return 0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b);
319: }
320: 
321: export function contrastRatio(a: Rgb, b: Rgb): number {
322:   const la = relativeLuminance(a);
323:   const lb = relativeLuminance(b);
324:   const lighter = Math.max(la, lb);
325:   const darker = Math.min(la, lb);
326:   return (lighter + 0.05) / (darker + 0.05);
327: }
328: 
329: /** Pick the theme color with the highest contrast against the background. */
330: function bestTextColor(background: string, theme: Theme): string {
331:   const bg = parseHexColor(background);
332:   if (!bg) return theme.foreground;
333:   const candidates = [
334:     theme.foreground,
335:     theme.background,
336:     theme.primaryForeground,
337:     "#000000",
338:     "#FFFFFF",
339:   ];
340:   let best = theme.foreground;
341:   let bestRatio = -1;
342:   for (const candidate of candidates) {
343:     const rgb = parseHexColor(candidate);
344:     if (!rgb) continue;
345:     const ratio = contrastRatio(rgb, bg);
346:     if (ratio > bestRatio) {
347:       best = candidate;
348:       bestRatio = ratio;
349:     }
350:   }
351:   return best.toUpperCase();
352: }
