1: // ---------------------------------------------------------------------------
2: // Design consistency check (plan/07 3.10) — deterministic audit of the
3: // document against the design system scales. Runs locally (no AI key), and
4: // returns safe style fixes that can be applied through the command manager.
5: //
6: // Rules:
7: //  - spacing: padding/margin/gap must sit on the spacing scale
8: //  - font-size: explicit sizes must sit on the type scale
9: //  - radius: border radius must use a radius token (or full)
10: //  - color: colors must match a theme token; near-duplicates are flagged
11: //  - font-family: explicit fonts must match the theme font
12: //  - type-scale: too many distinct font sizes in one document
13: // ---------------------------------------------------------------------------
14: 
15: import { defaultTokens } from "@ai-mockup-studio/design-system";
16: import {
17:   getComponentDefinition,
18:   type Theme,
19:   type UiDocument,
20:   type UiNode,
21:   type ViewportMode,
22: } from "@ai-mockup-studio/ui-schema";
23: import { applyPatchBatch } from "@ai-mockup-studio/ui-renderer";
24: 
25: export type ConsistencyRule =
26:   | "spacing"
27:   | "font-size"
28:   | "radius"
29:   | "color"
30:   | "font-family"
31:   | "type-scale";
32: 
33: export interface ConsistencyIssue {
34:   /** Stable id for list keys and targeted fixes. */
35:   id: string;
36:   rule: ConsistencyRule;
37:   severity: "warning" | "info";
38:   nodeId: string;
39:   nodeType: string;
40:   nodeLabel: string;
41:   /** The style key that drifted (padding, fontSize, color…). */
42:   property: string;
43:   message: string;
44:   suggestion: string;
45:   /** Safe style patch that resolves the issue. */
46:   fixStyles?: Record<string, unknown>;
47: }
48: 
49: const MAX_FONT_SIZES = 6;
50: const COLOR_DRIFT_DISTANCE = 40;
51: 
52: /** Token scales derived from the design system (source of truth). */
53: const SPACING_SCALE = new Set(Object.values(defaultTokens.spacing));
54: const FONT_SCALE = new Set([
55:   defaultTokens.typography.fontSizeXs,
56:   defaultTokens.typography.fontSizeSm,
57:   defaultTokens.typography.fontSizeBase,
58:   defaultTokens.typography.fontSizeLg,
59:   defaultTokens.typography.fontSizeXl,
60:   defaultTokens.typography.fontSize2xl,
61:   defaultTokens.typography.fontSize3xl,
62:   36,
63:   48,
64: ]);
65: const RADIUS_SCALE = new Set(Object.values(defaultTokens.radius));
66: const SPACING_KEYS = ["padding", "margin", "gap"] as const;
67: const COLOR_KEYS = ["color", "backgroundColor", "borderColor"] as const;
68: 
69: interface Rgb {
70:   r: number;
71:   g: number;
72:   b: number;
73: }
74: 
75: interface PaletteToken {
76:   name: string;
77:   value: string;
78: }
79: 
80: export function analyzeConsistency(
81:   doc: UiDocument,
82:   viewport: ViewportMode = "desktop",
83: ): ConsistencyIssue[] {
84:   const issues: ConsistencyIssue[] = [];
85:   const palette = themePalette(doc.theme);
86:   const explicitFontSizes = new Set<number>();
87:   const offPaletteColors = new Set<string>();
88: 
89:   const visit = (node: UiNode) => {
90:     if (node.hidden) return;
91:     const override = viewport === "desktop" ? undefined : node.responsive?.[viewport];
92:     const styles: Record<string, unknown> = { ...(node.styles ?? {}), ...(override ?? {}) };
93:     const definition = getComponentDefinition(node.type);
94:     const label = definition?.label ?? node.type;
95: 
96:     // --- Spacing scale ---------------------------------------------------
97:     for (const key of SPACING_KEYS) {
98:       const value = numericStyle(styles[key]);
99:       if (value === undefined || value <= 0 || SPACING_SCALE.has(value)) continue;
100:       const nearest = nearestValue(SPACING_SCALE, value);
101:       issues.push({
102:         id: `spacing:${node.id}:${key}`,
103:         rule: "spacing",
104:         severity: "warning",
105:         nodeId: node.id,
106:         nodeType: node.type,
107:         nodeLabel: label,
108:         property: key,
109:         message: `${key} = ${value}px không thuộc thang spacing (${formatScale(SPACING_SCALE)})`,
110:         suggestion: `Snap về ${nearest}px để giữ nhịp khoảng cách nhất quán.`,
111:         fixStyles: { [key]: nearest },
112:       });
113:     }
114: 
115:     // --- Type scale ------------------------------------------------------
116:     const fontSize = numericStyle(styles.fontSize);
117:     if (fontSize !== undefined) {
118:       explicitFontSizes.add(fontSize);
119:       if (!FONT_SCALE.has(fontSize)) {
120:         const nearest = nearestValue(FONT_SCALE, fontSize);
121:         issues.push({
122:           id: `font-size:${node.id}`,
123:           rule: "font-size",
124:           severity: "warning",
125:           nodeId: node.id,
126:           nodeType: node.type,
127:           nodeLabel: label,
128:           property: "fontSize",
129:           message: `fontSize = ${fontSize}px không thuộc type scale (${formatScale(FONT_SCALE)})`,
130:           suggestion: `Dùng ${nearest}px để đồng bộ với hệ thống typography.`,
131:           fixStyles: { fontSize: nearest },
132:         });
133:       }
134:     }
135: 
136:     // --- Radius tokens ---------------------------------------------------
137:     const radius = numericStyle(styles.borderRadius);
138:     if (
139:       radius !== undefined &&
140:       radius > 0 &&
141:       radius < 100 &&
142:       !RADIUS_SCALE.has(radius)
143:     ) {
144:       const nearest = nearestValue(RADIUS_SCALE, radius);
145:       issues.push({
146:         id: `radius:${node.id}`,
147:         rule: "radius",
148:         severity: "warning",
149:         nodeId: node.id,
150:         nodeType: node.type,
151:         nodeLabel: label,
152:         property: "borderRadius",
153:         message: `borderRadius = ${radius}px không khớp radius token`,
154:         suggestion: `Dùng ${nearest}px (radius token gần nhất).`,
155:         fixStyles: { borderRadius: nearest },
156:       });
157:     }
158: 
159:     // --- Font family -----------------------------------------------------
160:     if (
161:       typeof styles.fontFamily === "string" &&
162:       styles.fontFamily.trim() !== doc.theme.fontFamily.trim()
163:     ) {
164:       issues.push({
165:         id: `font-family:${node.id}`,
166:         rule: "font-family",
167:         severity: "warning",
168:         nodeId: node.id,
169:         nodeType: node.type,
170:         nodeLabel: label,
171:         property: "fontFamily",
172:         message: `fontFamily "${styles.fontFamily}" khác theme "${doc.theme.fontFamily}"`,
173:         suggestion: "Dùng font family của theme để giữ nhận diện thống nhất.",
174:         fixStyles: { fontFamily: doc.theme.fontFamily },
175:       });
176:     }
177: 
178:     // --- Colors ----------------------------------------------------------
179:     for (const key of COLOR_KEYS) {
180:       const value = styles[key];
181:       if (typeof value !== "string") continue;
182:       const rgb = parseHexColor(value);
183:       if (!rgb) continue;
184:       const normalized = normalizeHex(value);
185:       if (palette.some((token) => token.value === normalized)) continue;
186: 
187:       offPaletteColors.add(normalized);
188:       const near = nearestPalette(value, palette);
189:       if (near && near.distance <= COLOR_DRIFT_DISTANCE) {
190:         issues.push({
191:           id: `color:${node.id}:${key}`,
192:           rule: "color",
193:           severity: "warning",
194:           nodeId: node.id,
195:           nodeType: node.type,
196:           nodeLabel: label,
197:           property: key,
198:           message: `${key} ${value} gần token ${near.token.name} (${near.token.value}) nhưng không khớp`,
199:           suggestion: `Dùng đúng token ${near.token.value} để tránh lệch màu.`,
200:           fixStyles: { [key]: near.token.value },
201:         });
202:       }
203:     }
204: 
205:     node.children?.forEach(visit);
206:   };
207: 
208:   visit(doc.root);
209: 
210:   if (explicitFontSizes.size > MAX_FONT_SIZES) {
211:     issues.push({
212:       id: "type-scale:too-many",
213:       rule: "type-scale",
214:       severity: "info",
