245: export function applyConsistencyFixes(
246:   doc: UiDocument,
247:   issues: ConsistencyIssue[],
248:   viewport: ViewportMode = "desktop",
249: ): UiDocument | null {
250:   const byNode = new Map<string, Record<string, unknown>>();
251:   for (const issue of issues) {
252:     if (!issue.fixStyles) continue;
253:     byNode.set(issue.nodeId, {
254:       ...(byNode.get(issue.nodeId) ?? {}),
255:       ...issue.fixStyles,
256:     });
257:   }
258:   if (byNode.size === 0) return null;
259: 
260:   const patches = [...byNode].map(([targetId, styles]) => {
261:     if (viewport === "desktop") {
262:       return { op: "style" as const, targetId, styles };
263:     }
264:     return {
265:       op: "update" as const,
266:       targetId,
267:       changes: Object.fromEntries(
268:         Object.entries(styles).map(([key, value]) => [
269:           `responsive.${viewport}.${key}`,
270:           value,
271:         ]),
272:       ),
273:     };
274:   });
275:   return applyPatchBatch(doc, patches);
