284: function numericStyle(value: unknown): number | undefined {
285:   if (typeof value === "number" && Number.isFinite(value)) return value;
286:   if (typeof value === "string") {
287:     const match = /^(-?\d+(?:\.\d+)?)px$/.exec(value.trim());
288:     if (match) return Number(match[1]);
289:   }
290:   return undefined;
291: }
292: 
293: function nearestValue(values: Set<number>, target: number): number {
294:   let best = target;
295:   let bestDistance = Number.POSITIVE_INFINITY;
296:   for (const value of values) {
297:     const distance = Math.abs(value - target);
298:     if (distance < bestDistance) {
299:       best = value;
300:       bestDistance = distance;
301:     }
302:   }
303:   return best;
304: }
305: 
306: function formatScale(values: Set<number>): string {
307:   return [...values]
308:     .sort((a, b) => a - b)
309:     .slice(0, 10)
310:     .join("/");
311: }
312: 
313: function parseHexColor(value: string): Rgb | null {
314:   const hex = value.trim();
315:   const short = /^#([0-9a-f]{3})$/i.exec(hex);
316:   if (short) {
317:     return {
318:       r: parseInt(short[1][0] + short[1][0], 16),
319:       g: parseInt(short[1][1] + short[1][1], 16),
320:       b: parseInt(short[1][2] + short[1][2], 16),
321:     };
322:   }
323:   const long = /^#([0-9a-f]{6})$/i.exec(hex);
324:   if (!long) return null;
325:   return {
326:     r: parseInt(long[1].slice(0, 2), 16),
327:     g: parseInt(long[1].slice(2, 4), 16),
328:     b: parseInt(long[1].slice(4, 6), 16),
329:   };
330: }
331: 
332: function normalizeHex(value: string): string {
333:   const rgb = parseHexColor(value);
334:   if (!rgb) return value.trim().toLowerCase();
335:   return `#${[rgb.r, rgb.g, rgb.b]
336:     .map((channel) => channel.toString(16).padStart(2, "0"))
337:     .join("")}`.toLowerCase();
338: }
339: 
340: function themePalette(theme: Theme): PaletteToken[] {
341:   return [
342:     { name: "primary", value: theme.primary },
343:     { name: "primaryForeground", value: theme.primaryForeground },
344:     { name: "background", value: theme.background },
345:     { name: "foreground", value: theme.foreground },
346:     { name: "muted", value: theme.muted },
347:     { name: "mutedForeground", value: theme.mutedForeground },
348:     { name: "border", value: theme.border },
349:   ]
350:     .map((token) => ({ ...token, value: normalizeHex(token.value) }))
351:     .filter((token) => parseHexColor(token.value) !== null);
352: }
353: 
354: function nearestPalette(
355:   value: string,
356:   palette: PaletteToken[],
357: ): { token: PaletteToken; distance: number } | null {
358:   const rgb = parseHexColor(value);
359:   if (!rgb) return null;
360:   let best: { token: PaletteToken; distance: number } | null = null;
361:   for (const token of palette) {
362:     const tokenRgb = parseHexColor(token.value);
363:     if (!tokenRgb) continue;
364:     const distance = Math.sqrt(
365:       (rgb.r - tokenRgb.r) ** 2 + (rgb.g - tokenRgb.g) ** 2 + (rgb.b - tokenRgb.b) ** 2,
366:     );
367:     if (!best || distance < best.distance) best = { token, distance };
368:   }
369:   return best;
370: }
