88: @Injectable()
89: export class MetricsService {
90:   private readonly startedAt = new Date();
91:   private totalRequests = 0;
92:   private readonly byStatus = new Map<number, number>();
93:   private readonly byMethod = new Map<string, number>();
94:   private readonly routes = new Map<string, RouteMetric>();
95:   private readonly latencySamples: number[] = [];
96:   private readonly ai: Record<AiKind, AiMetric> = {
97:     generate: emptyAiMetric(),
98:     edit: emptyAiMetric(),
99:     critique: emptyAiMetric(),
100:     dummy: emptyAiMetric(),
101:     responsive: emptyAiMetric(),
102:   };
103: 
104:   recordRequest(method: string, route: string, status: number, durationMs: number): void {
105:     this.totalRequests += 1;
106:     this.byStatus.set(status, (this.byStatus.get(status) ?? 0) + 1);
107:     this.byMethod.set(method, (this.byMethod.get(method) ?? 0) + 1);
108: 
109:     const key = `${method} ${route}`;
110:     const metric = this.routes.get(key) ?? {
111:       method,
112:       route,
113:       count: 0,
114:       errors: 0,
115:       totalMs: 0,
116:       maxMs: 0,
117:     };
118:     metric.count += 1;
119:     metric.totalMs += durationMs;
120:     metric.maxMs = Math.max(metric.maxMs, durationMs);
121:     if (status >= 500) metric.errors += 1;
122:     this.routes.set(key, metric);
123: 
124:     this.latencySamples.push(durationMs);
125:     if (this.latencySamples.length > MAX_LATENCY_SAMPLES) {
126:       this.latencySamples.shift();
127:     }
128:   }
129: 
130:   recordAi(
131:     kind: AiKind,
132:     outcome: AiOutcome,
133:     durationMs: number,
134:     usage: AiUsage = {},
135:     attempts = 1,
136:   ): void {
137:     const metric = this.ai[kind];
138:     metric.requests += 1;
139:     metric.byOutcome[outcome] += 1;
140:     metric.totalMs += durationMs;
141:     metric.retries += Math.max(0, attempts - 1);
142:     metric.promptTokens += usage.promptTokens ?? 0;
143:     metric.completionTokens += usage.completionTokens ?? 0;
144:   }
145: 
146:   snapshot(): MetricsSnapshot {
147:     const sorted = [...this.latencySamples].sort((a, b) => a - b);
148:     const sum = sorted.reduce((total, value) => total + value, 0);
149:     const totalErrors = [...this.byStatus.entries()]
150:       .filter(([status]) => status >= 500)
151:       .reduce((total, [, count]) => total + count, 0);
152:     const p95 = round(percentile(sorted, 95));
153:     const alerts: string[] = [];
154: 
155:     if (this.totalRequests > 0) {
156:       const errorRate = totalErrors / this.totalRequests;
157:       const maxErrorRate = envNumber("METRICS_ERROR_RATE_THRESHOLD", 0.05);
158:       if (errorRate > maxErrorRate) {
159:         alerts.push(
160:           `error_rate ${(errorRate * 100).toFixed(1)}% > ${(maxErrorRate * 100).toFixed(0)}%`,
161:         );
162:       }
163:     }
164: 
165:     const maxP95 = envNumber("METRICS_P95_MS_THRESHOLD", 1000);
166:     if (sorted.length >= 10 && p95 > maxP95) {
167:       alerts.push(`latency_p95 ${p95}ms > ${maxP95}ms`);
168:     }
169: 
170:     const aiRequests =
171:       this.ai.generate.requests +
172:       this.ai.edit.requests +
173:       this.ai.critique.requests +
174:       this.ai.dummy.requests +
175:       this.ai.responsive.requests;
176:     const aiFallbacks =
177:       this.ai.generate.byOutcome.fallback +
178:       this.ai.edit.byOutcome.fallback +
179:       this.ai.critique.byOutcome.fallback +
180:       this.ai.dummy.byOutcome.fallback +
181:       this.ai.responsive.byOutcome.fallback;
182:     if (aiRequests >= 5) {
183:       const fallbackRate = aiFallbacks / aiRequests;
184:       const maxFallbackRate = envNumber("METRICS_AI_FALLBACK_THRESHOLD", 0.2);
185:       if (fallbackRate > maxFallbackRate) {
186:         alerts.push(
187:           `ai_fallback_rate ${(fallbackRate * 100).toFixed(1)}% > ${(maxFallbackRate * 100).toFixed(0)}%`,
188:         );
189:       }
190:     }
191: 
192:     return {
193:       startedAt: this.startedAt.toISOString(),
194:       uptimeSeconds: Math.round(process.uptime()),
195:       requests: {
196:         total: this.totalRequests,
197:         byStatus: Object.fromEntries(
198:           [...this.byStatus.entries()]
199:             .sort(([a], [b]) => a - b)
200:             .map(([status, count]) => [String(status), count]),
201:         ),
202:         byMethod: Object.fromEntries(this.byMethod),
203:         errors: totalErrors,
204:       },
205:       latencyMs: {
206:         samples: sorted.length,
207:         avg: sorted.length ? round(sum / sorted.length) : 0,
208:         p50: round(percentile(sorted, 50)),
209:         p95,
210:         p99: round(percentile(sorted, 99)),
211:         max: round(sorted.length ? sorted[sorted.length - 1] : 0),
212:       },
213:       routes: [...this.routes.values()]
214:         .sort((a, b) => b.count - a.count)
215:         .map((metric) => ({
216:           ...metric,
217:           totalMs: round(metric.totalMs),
218:           maxMs: round(metric.maxMs),
219:         })),
220:       ai: {
221:         generate: { ...this.ai.generate, totalMs: round(this.ai.generate.totalMs) },
222:         edit: { ...this.ai.edit, totalMs: round(this.ai.edit.totalMs) },
223:         critique: { ...this.ai.critique, totalMs: round(this.ai.critique.totalMs) },
224:         dummy: { ...this.ai.dummy, totalMs: round(this.ai.dummy.totalMs) },
225:         responsive: { ...this.ai.responsive, totalMs: round(this.ai.responsive.totalMs) },
226:       },
227:       alerts,
228:     };
229:   }
230: }
