413: function renderHtmlNode(node: CodeNode, indent: number): string {
414:   const pad = "  ".repeat(indent);
415:   const attrs = [
416:     htmlStyle(node.style) ? `style="${escapeHtml(htmlStyle(node.style))}"` : "",
417:     ...Object.entries(node.attrs)
418:       .filter(([, value]) => value !== "")
419:       .map(([key, value]) => `${key}="${escapeHtml(value)}"`),
420:   ]
421:     .filter(Boolean)
422:     .join(" ");
