425: 
426:   if (VOID_TAGS.has(node.tag)) return `${pad}${open} />`;
427: 
428:   if (node.text !== undefined && node.children.length === 0) {
429:     return `${pad}${open}>${escapeHtml(node.text)}</${node.tag}>`;
430:   }
431: 
432:   if (node.children.length === 0 && node.text === undefined) {
433:     return `${pad}${open}></${node.tag}>`;
434:   }
435: 
436:   const inner = [
437:     ...(node.text !== undefined ? [`${"  ".repeat(indent + 1)}${escapeHtml(node.text)}`] : []),
438:     ...node.children.map((child) => renderHtmlNode(child, indent + 1)),
439:   ].join("\n");
440: 
441:   return `${pad}${open}>\n${inner}\n${pad}</${node.tag}>`;
442: }
