66:  */
67: export interface UiNode {
68:   id: string;
69:   type: string;
70:   name?: string;
71:   /** Layer visibility — hidden nodes stay in the document but are not rendered. */
72:   hidden?: boolean;
73:   /** Locked nodes cannot be selected/resized/moved from the canvas. */
74:   locked?: boolean;
75:   /** Per-breakpoint style overrides (desktop uses `styles` as the base). */
76:   responsive?: ResponsiveStyles;
77:   props?: Record<string, unknown>;
78:   styles?: UiStyles;
79:   children?: UiNode[];
80: }
81: 
82: /** Tablet/mobile overrides merged on top of the base (desktop) styles. */
83: export interface ResponsiveStyles {
84:   tablet?: UiStyles;
85:   mobile?: UiStyles;
86: }
87: 
88: /** The container/hierarchy rules per component type family. */
89: export interface ComponentDefinition {
90:   type: string;
91:   category: ComponentCategory;
92:   label: string;
93:   /** Whether this component can contain children. */
94:   isContainer: boolean;
95:   /** Allowed child categories (used by the validator). */
96:   allowedChildren?: ComponentCategory[];
97:   defaultProps: Record<string, unknown>;
98:   defaultStyles?: UiStyles;
99: }
100: 
101: /** A page document — the unit that is saved to DB (documents.jsonb). */
102: export interface UiDocument {
103:   schemaVersion: string;
104:   id: string;
105:   pageId: string;
106:   name: string;
107:   viewport: Viewport;
108:   theme: Theme;
109:   root: UiNode;
110: }
