112: // ---------------------------------------------------------------------------
113: // Patch operations
114: // ---------------------------------------------------------------------------
115: 
116: export type PatchOperationKind =
117:   | "add"
118:   | "update"
119:   | "remove"
120:   | "move"
121:   | "replace"
122:   | "style";
123: 
124: export interface AddPatch {
125:   op: "add";
126:   parentId: string;
127:   /** Index inside parent.children (default: append at end). */
128:   index?: number;
129:   node: UiNode;
130: }
131: 
132: export interface UpdatePatch {
133:   op: "update";
134:   targetId: string;
135:   /** Deep-ish merge into node.props (dot-path keys supported, e.g. "props.width"). */
136:   changes: Record<string, unknown>;
137: }
138: 
139: export interface RemovePatch {
140:   op: "remove";
141:   targetId: string;
142: }
143: 
144: export interface MovePatch {
145:   op: "move";
146:   targetId: string;
147:   newParentId: string;
148:   index?: number;
149: }
150: 
151: export interface ReplacePatch {
152:   op: "replace";
153:   targetId: string;
154:   node: UiNode;
155: }
156: 
157: export interface StylePatch {
158:   op: "style";
159:   targetId: string;
160:   styles: UiStyles;
161: }
162: 
163: export type UiPatch =
164:   | AddPatch
165:   | UpdatePatch
166:   | RemovePatch
167:   | MovePatch
168:   | ReplacePatch
169:   | StylePatch;
170: 
171: /** A session carries the patch list so the client can replay / sync. */
172: export interface PatchBatch {
173:   documentId: string;
174:   patches: UiPatch[];
175: }
